import{_ as n,o as i,c as t,a3 as l}from"./chunks/framework.B9qR_F1m.js";const m=JSON.parse('{"title":"Versionen","description":"","frontmatter":{},"headers":[],"relativePath":"referenz/versionen.md","filePath":"referenz/versionen.md"}'),r={name:"referenz/versionen.md"};function a(s,e,u,d,o,h){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="versionen" tabindex="-1">Versionen <a class="header-anchor" href="#versionen" aria-label="Permalink to &quot;Versionen&quot;">​</a></h1><p>Die Desktop-App aktualisiert sich selbst. Alle Downloads: <a href="https://github.com/Leichtester/shardwing-releases/releases" target="_blank" rel="noreferrer">Releases</a>.</p><h2 id="_0-8-11-·-14-11-2026" tabindex="-1">0.8.11 · 14.11.2026 <a class="header-anchor" href="#_0-8-11-·-14-11-2026" aria-label="Permalink to &quot;0.8.11 · 14.11.2026&quot;">​</a></h2><p><strong>Air Defense: Alarmrotten, Limits, Stärke</strong></p><ul><li>Alarmrotten: eine Rotte steht mit Late Activation am Platz bereit und startet mit dem KI-Skript, sobald ein Gegner lange genug im Alarmgebiet ist; Mindestzeit, Verzögerung, Netz-Knoten und eigene Sensoren einstellbar</li><li>Limits je Seite, Platz, Staffel und Gebiet: wie viele Flights gleichzeitig in der Luft oder im Commit sein dürfen und wie oft eine Staffel alarmiert werden darf</li><li>Stärke „schwach, mittel, stark“ setzt Limits und Reaktion der Alarmrotten einer Seite mit einem Klick</li><li>Im Popup eines Gebiets: „CAP-Station hier“ und „Alarmrotte hier“</li><li>Intel: Plätze mit Jägern und CAP-Zonen lassen sich wie SAMs für alle oder einzelne Flights freigeben; neu sind sie verborgen</li></ul><p><strong>Sicherheit und Verlässlichkeit</strong></p><ul><li>Desktop: Shardwing liest und schreibt nur noch Dateien, die du selbst geöffnet, gespeichert oder auf das Fenster gezogen hast. Eine Mission aus der Liste „Zuletzt“, die du vor diesem Update geöffnet hast, fragt einmal mit dem Öffnen-Dialog nach</li><li>Namen aus Missionsdateien werden auf der Karte immer als Text angezeigt</li><li>Geteilte Missionen: Kann der Server die .miz mit dem aktuellen Stand nicht bauen, sagt er das, statt eine ältere Fassung zum Herunterladen anzubieten</li><li>Zu große Uploads bricht der Server schon beim Empfang ab</li><li>Desktop: Update-Komponente aktualisiert; behebt Sicherheitslücken beim Entpacken von Archiven</li><li>Eine Planung aus einer neueren Shardwing-Version oder eine beschädigte wird nicht mehr still überschrieben: Shardwing meldet sie beim Öffnen und hebt sie beim Speichern in der .miz auf (<code>Shardwing/planner-unlesbar.json</code>)</li></ul><h2 id="_0-8-10-·-13-11-2026" tabindex="-1">0.8.10 · 13.11.2026 <a class="header-anchor" href="#_0-8-10-·-13-11-2026" aria-label="Permalink to &quot;0.8.10 · 13.11.2026&quot;">​</a></h2><p><strong>Gebiete für Missions-Skripte (IADS-Bereich)</strong></p><ul><li>Gebiete als Polygon oder Kreis auf die Karte zeichnen; sie bekommen eine feste ID für CAP und Alarmrotten</li><li>Klick auf ein Gebiet zeigt Name, Größe und Hinweise; umbenennen und löschen direkt dort</li><li>Punkte, Mitte und Radius ziehen; Höhenband im Inspector</li><li>Piloten sehen keine Gebiete</li></ul><p><strong>Air Defense: Netz, Jäger, Gebiete</strong></p><ul><li>Der Bereich „IADS“ heißt jetzt „Air Defense“, mit Schalter Rot/Blau und den Reitern Netz, Jäger und Gebiete</li><li>Staffeln: Platz, Vorrat an Maschinen und eine KI-Gruppe der Mission als Vorlage (Typ, Beladung, Lackierung, Skill)</li><li>CAP-Stationen wie beim Tanker: Track auf der Karte setzen, Fenster, Standzeit und Überlappung wählen; Shardwing legt die Rotten als Ablösekette mit Startzeiten an</li><li>Hinweise, wenn die erste Rotte zu spät am Track ist, die Staffel zu wenig Maschinen hat oder sich die Station seit dem Planen geändert hat</li><li>Piloten sehen weder Staffeln noch Stationen</li></ul><p><strong>Air Defense: Commit im Gebiet</strong></p><ul><li>CAP-Stationen können mit dem KI-Skript im Gebiet committen: im Pattern nur Feuer erwidern, frei, solange ein Gegner im Gebiet ist</li><li>Stationen hängen am IADS-Netz (Kommandoposten, Fernmeldeknoten) und nutzen dessen Lagebild; ohne Netz sehen sie nur mit dem eigenen Radar</li><li>Schalter „KI-Skript beim Speichern einbauen“ jetzt auch im Reiter Jäger; die Gebiete kommen mit in die Mission</li><li>IADS-Skript 1.1: ein dunkles Radar meldet nichts mehr; eine SAM ohne Frühwarnradar im Sektor sendet dauerhaft</li></ul><p><strong>Korrekturen am Mac</strong></p><ul><li>Eine Sollzeit zu ziehen markiert keinen Text mehr</li><li><kbd>Esc</kbd> bleibt in Shardwing und verlässt nicht mehr das Vollbild</li></ul><h2 id="_0-8-9-·-12-11-2026" tabindex="-1">0.8.9 · 12.11.2026 <a class="header-anchor" href="#_0-8-9-·-12-11-2026" aria-label="Permalink to &quot;0.8.9 · 12.11.2026&quot;">​</a></h2><p><strong>Flugplan im Reiter „Route“</strong></p><ul><li>Eine Tabelle für die ganze Route: wo, wann und was der Jet anzeigt; die Zeiten rechnen beim Ändern sofort mit</li><li>Sollzeiten per Ziehen an einen Punkt hängen; gekoppelte Cartridges, Missionsroute und Lineup Card bekommen die geplanten Zeiten beim Speichern</li><li>Zeiten für jedes Flugmuster, bei der F/A-18C je Route 1–3</li></ul><p><strong>Flugplan auf der Karte</strong></p><ul><li>Zeiten stehen an den Punkten des gewählten Flights</li><li>Einen Punkt in den Ring einer Sollzeit ziehen, und er rastet ein; wieder herausgezogen, löst er sie</li><li>Halten erscheint als Oval am Punkt</li><li>Cartridge- und Missionsroute haben dieselben Griffe; ein F-16C-Steerpoint gehört zu genau einer Route</li></ul><p><strong>F/A-18C-Cartridge</strong></p><ul><li>Routen 1–3 je Waypoint wählbar</li><li>TACAN-Liste bearbeitbar</li><li>MEZ direkt aus dem Intel übernehmen</li></ul><h2 id="_0-8-8-·-12-11-2026" tabindex="-1">0.8.8 · 12.11.2026 <a class="header-anchor" href="#_0-8-8-·-12-11-2026" aria-label="Permalink to &quot;0.8.8 · 12.11.2026&quot;">​</a></h2><p><strong>F/A-18C-Cartridge</strong></p><ul><li>Eine im Mission Editor erstellte Hornet-Cartridge kommt unverändert zurück: Funk-Presets, Routen 2 und 3, ETA, mehrere Korridore und die Radarwarner-Tabellen bleiben erhalten</li><li>Die Punkte des Korridors lassen sich auf der Karte ziehen</li><li>MEZ-Typen mit Namen und Radius wie im Mission Editor</li></ul><p><strong>Bedrohungen</strong></p><ul><li>Threat-Typen und Reichweiten kommen jetzt aus dem Mission Editor (alle 51 Typen) – für F-16C, F/A-18C und das Intel</li></ul><h2 id="_0-8-7-·-11-11-2026" tabindex="-1">0.8.7 · 11.11.2026 <a class="header-anchor" href="#_0-8-7-·-11-11-2026" aria-label="Permalink to &quot;0.8.7 · 11.11.2026&quot;">​</a></h2><p><strong>Schneller arbeiten</strong></p><ul><li>Die Leiste zeigt je Bereich den Stand; die Ampel daneben listet unter „Was fehlt noch?“ die offenen Punkte je Flight und springt mit einem Klick an die richtige Stelle</li><li>Suche mit <kbd>⌘K</kbd> / <kbd>Strg+K</kbd>: Flights, Wegpunkte, Stellungen, Planungspunkte, Kneeboards und Aktionen</li><li>Neue Kürzel: <kbd>1</kbd>–<kbd>6</kbd> wechseln den Bereich, <kbd>⌥↑</kbd> <kbd>⌥↓</kbd> den Flight, <kbd>F</kbd> holt die Karte auf die Auswahl zurück</li><li>Rechtsklick auf die Karte öffnet ein Menü für diese Stelle: Wegpunkt anhängen, Planungspunkt, Grafik, Bedrohung, Messen, Koordinate kopieren</li></ul><p><strong>Flights</strong></p><ul><li>Neue Reiter „Zeiten“ und „Status“: Timing und Prüfungen des Flights ohne Bereichswechsel</li><li>‹ › am Flight blättert zum vorherigen und nächsten</li></ul><p><strong>Panel und Karte</strong></p><ul><li>Drei Symbole oben rechts im Panel legen es unter die Karte, rechts daneben oder über die ganze Höhe; die App merkt sich das je Bereich</li><li>Bei ganzer Höhe und im Timing bleibt die Karte als kleines Fenster in der Ecke und folgt dem gewählten Flight</li></ul><p><strong>Ausgeben</strong></p><ul><li>Ein Blatt für alles, was rausgeht (<kbd>⌘E</kbd> / <kbd>Strg+E</kbd>): Speichern mit eingebetteten Kneeboards, PDF, Kneeboard-Ordner, Briefing und Teilen</li></ul><h2 id="_0-8-6-·-10-11-2026" tabindex="-1">0.8.6 · 10.11.2026 <a class="header-anchor" href="#_0-8-6-·-10-11-2026" aria-label="Permalink to &quot;0.8.6 · 10.11.2026&quot;">​</a></h2><p><strong>Übersicht</strong></p><ul><li>Die App startet in der Übersicht</li><li>Die Paket-Seite zeigt oben die Kneeboards und darunter „Kneeboards für den Jet“: das ganze Paket als ZIP oder PDF, dazu je Flight PDF und ZIP, mit Hinweisen, wie die Seiten in den Jet kommen</li><li>Server (für Designer auf einem Server) und Wetter haben eigene Seiten in der Übersicht; die Paket-Seite sieht mit und ohne Server gleich aus</li><li>Die Intel-Karte ist von der Paket-Seite weg, auf der Seite eines Flights bleibt sie</li></ul><h2 id="_0-8-5-·-10-11-2026" tabindex="-1">0.8.5 · 10.11.2026 <a class="header-anchor" href="#_0-8-5-·-10-11-2026" aria-label="Permalink to &quot;0.8.5 · 10.11.2026&quot;">​</a></h2><p><strong>Mission abspielen</strong></p><ul><li>Neuer Knopf „▶ Ablauf“ in Übersicht und Timing: Die Karte spielt die ganze Mission nach dem Timing ab, alle Flights bewegen sich mit Callsign und Höhe</li><li>Regler mit Sprungmarken für H-Hour, Starts, Push, Zeit am Ziel, Tanker und Annäherungen, Tempo ×10, ×60 und ×300</li><li>Tanker und AWACS fliegen ihre Tracks, die Linie in der Sync-Matrix läuft mit</li></ul><p><strong>Briefing präsentieren</strong></p><ul><li>„▶ Briefing präsentieren“ in der Übersicht zeigt das Briefing als fertige Folien im Vollbild, gedacht für die Bildschirmfreigabe</li><li>Folien für Lage und Auftrag, Wetter, Kräfte, Gesamtlage, Zeitachse, Ablauf, Funk und jeden Flight; die Karte bleibt dabei bedienbar</li><li>Blättern mit den Pfeiltasten, einzelne Folien lassen sich ausblenden; Piloten sehen ihre eigene Fassung</li></ul><h2 id="_0-8-4-·-10-11-2026" tabindex="-1">0.8.4 · 10.11.2026 <a class="header-anchor" href="#_0-8-4-·-10-11-2026" aria-label="Permalink to &quot;0.8.4 · 10.11.2026&quot;">​</a></h2><p><strong>Eigene Karte</strong></p><ul><li>Neue Grundkarte „Shardwing“ im Stil der DCS-Kartenansicht: helles Land, blaues Wasser, Orte als Flächen, rotbraune Hauptstraßen, Namen nur in lateinischer Schrift</li><li>Kommt mitsamt Geländedaten und Schriften vom eigenen Server; die Geländekarte braucht keinen Dienst in den USA mehr</li><li>Im Ebenen-Menü unter „Grundkarte“ umschaltbar, OpenFreeMap bleibt als Alternative</li></ul><h2 id="_0-8-3-·-09-11-2026" tabindex="-1">0.8.3 · 09.11.2026 <a class="header-anchor" href="#_0-8-3-·-09-11-2026" aria-label="Permalink to &quot;0.8.3 · 09.11.2026&quot;">​</a></h2><ul><li>Der Browser zeigt nach einem Update nicht mehr die alte Version aus dem Cache</li></ul><h2 id="_0-8-2-·-09-11-2026" tabindex="-1">0.8.2 · 09.11.2026 <a class="header-anchor" href="#_0-8-2-·-09-11-2026" aria-label="Permalink to &quot;0.8.2 · 09.11.2026&quot;">​</a></h2><p><strong>Geländekarte</strong></p><ul><li>Neue Kartenebene „Geländekarte“ im Stil einer Fliegerkarte: Höhenschichten in Farbstufen (1000, 2000, 3000, 5000, 7000, 9000, 12000, 15000 ft), Relief und Höhenlinien in Fuß</li><li>Gibt es für jede DCS-Karte, auch für Sinai, Kola, Afghanistan, Iraq und Falklands, und erscheint ebenso auf den Kartenseiten der Kneeboards</li><li>Einschalten über das Ebenen-Menü oben links auf der Karte unter „Karte“</li></ul><h2 id="_0-8-1-·-09-11-2026" tabindex="-1">0.8.1 · 09.11.2026 <a class="header-anchor" href="#_0-8-1-·-09-11-2026" aria-label="Permalink to &quot;0.8.1 · 09.11.2026&quot;">​</a></h2><p><strong>Testphase</strong></p><ul><li>Shardwing öffnet sich während der Testphase nur noch mit einem Schlüssel: In der Desktop-App einmal beim Start eingeben, danach läuft sie auch offline. Es ist derselbe Schlüssel wie zum Teilen, du bekommst ihn von deiner Staffel oder als Tester</li><li>Piloten mit einem Missionslink brauchen keinen Schlüssel</li><li>Oben rechts und klein auf jedem Kneeboard steht, für wen Shardwing freigegeben ist</li><li>Testversionen laufen 60 Tage, das nächste Update verlängert</li></ul><h2 id="_0-8-0-·-09-11-2026" tabindex="-1">0.8.0 · 09.11.2026 <a class="header-anchor" href="#_0-8-0-·-09-11-2026" aria-label="Permalink to &quot;0.8.0 · 09.11.2026&quot;">​</a></h2><p><strong>Flugplätze</strong></p><ul><li>Neue Kneeboard-Vorlage „Flugplätze“: eine Übersicht je Platz mit Bahnen, Rollwegen samt Namen, Vorfeldern und Sheltern, dazu Höhe, Tower, TACAN und Anflüge. Die Stände der Flights sind in ihrer Farbe mit Rufzeichen markiert</li><li>Standardmäßig die Start- und Landeplätze der Flights, auf Wunsch mit den Ausweichplätzen oder frei gewählt</li><li>Die Übersichten kommen aus OpenStreetMap und sind auf die DCS-Bahnen ausgerichtet, für rund 260 Plätze auf allen Karten außer den WWII-Karten. Wo OSM nicht passt, gibt es eine schematische Seite aus den DCS-Daten</li><li>Auf der Karte erscheinen die Übersichten beim Heranzoomen mit der Ebene Flugplätze</li></ul><h2 id="_0-7-0-·-09-11-2026" tabindex="-1">0.7.0 · 09.11.2026 <a class="header-anchor" href="#_0-7-0-·-09-11-2026" aria-label="Permalink to &quot;0.7.0 · 09.11.2026&quot;">​</a></h2><p><strong>Staffeln</strong></p><ul><li>Staffel-Zugänge: Jede Staffel hat einen Schlüssel zum Teilen und eine feste Zahl an Slots für Missionen auf dem Server</li><li>Staffel-Panel für die Staffelführung (Missionen der Staffel sehen und löschen), Verwaltung der Staffeln im Admin-Panel</li></ul><p><strong>Englisch</strong></p><ul><li>Kneeboards auf Deutsch oder Englisch, einstellbar je Mission (Lineup Card, Comm Card, Karten, Angriffe, Wetter, automatische Seiten)</li><li>Handbuch-Einstieg und Landing Page auch auf Englisch</li></ul><p><strong>Sonstiges</strong></p><ul><li>Neue Adressen: Landing Page auf <code>https://shardwing.de</code>, die App auf <code>https://app.shardwing.de</code>, beide ohne Port. In der Desktop-App als Server <code>https://app.shardwing.de</code> eintragen</li><li>Navigation: Übersicht, Intel, Planung, Timing, Flights, Kneeboards; „Zeichnungen“ heißt jetzt „Planung“</li></ul><h2 id="_0-6-0-·-08-11-2026" tabindex="-1">0.6.0 · 08.11.2026 <a class="header-anchor" href="#_0-6-0-·-08-11-2026" aria-label="Permalink to &quot;0.6.0 · 08.11.2026&quot;">​</a></h2><ul><li>Ziel AO und das Gebiet bei TOO: neben KB, ROZ, NFA und RFA auch eigene Flächen aus den Zeichnungen (Kill Box, Fläche, Rechteck, Kreis, Oval) der eigenen Seite und von Common</li><li>Startseite aufgeräumt: Buttons so breit wie das Ablagefeld, „Link öffnen“ darunter, Punkte zwischen Impressum, Datenschutz und Lizenzen mittig</li></ul><h2 id="_0-5-12-·-08-11-2026" tabindex="-1">0.5.12 · 08.11.2026 <a class="header-anchor" href="#_0-5-12-·-08-11-2026" aria-label="Permalink to &quot;0.5.12 · 08.11.2026&quot;">​</a></h2><p><strong>Timing und Planungspunkte</strong></p><ul><li>Push und Ziel stehen als feste Sollzeiten zwischen den anderen, verknüpft mit dem Auftrag und per Ziehen sortierbar; doppelte Zeiten am selben Punkt werden zusammengeführt</li><li>Neue Planungspunkte TGT (Zielgebiet, als Ziel wählbar) und Fix (ohne feste Rolle); TOO lässt sich auf ein Gebiet eingrenzen</li><li>Flights sehen alle Planungspunkte ihrer Seite und setzen Steerpoints in der DTC darauf („auf …“)</li><li>Absturz beim Wechsel von einem Flight auf einen Tanker im Timing behoben</li></ul><p><strong>Tanker und Karte</strong></p><ul><li>Ablöse-Tanker sind markiert, Zeitplan und Skript bei ihnen ausgegraut; ein gelöschter Tanker nimmt seinen Track mit</li><li>Esc während des Ziehens lässt los, auch bei Wegpunkten auf der Flight-Seite</li><li>Zeichnungen: Einheiten nach Seite einblenden (Blue, Red, Neutral)</li></ul><p><strong>Übersicht und Darstellung</strong></p><ul><li>Callsigns &amp; Aufgaben als eigene Seite in der Übersicht</li><li>Eigene Icons statt Emojis, TOS-Rechner mit gleich breiten Steerpoint-Feldern, Elevation am Planungspunkt nicht mehr verdeckt</li></ul><h2 id="_0-5-11-·-07-11-2026" tabindex="-1">0.5.11 · 07.11.2026 <a class="header-anchor" href="#_0-5-11-·-07-11-2026" aria-label="Permalink to &quot;0.5.11 · 07.11.2026&quot;">​</a></h2><p><strong>Planungspunkte und Timing</strong></p><ul><li>Holdings sind jetzt Planungspunkte mit direkter Höhe statt Höhenbändern; Planungspunkte auf Wunsch gleich für alle Player-Flights</li><li>Jeder Flight bekommt ein Ziel: eine Bodengruppe (wird Zielangabe), ein AO oder Target of Opportunity ohne genaue Angaben</li><li>Sollzeiten per Ziehen sortieren, mit Warnung bei zu knappen Abständen</li><li>Übertragen neu: einzelne Teile und Sollzeiten auswählen und auf alle Player-Flights, alle oder einzelne Staffeln übertragen</li></ul><p><strong>TOS-Rechner und AAR</strong></p><ul><li>TOS-Rechner mit Fenster und Einrasten</li><li>AAR-Slot ohne feste Zeit: der Pilot meldet seine Zeit aus dem TOS-Rechner, der Designer sieht sie im Timing</li><li>Rufname, Frequenz und TACAN des Tankers stehen nicht mehr in der Track-Grafik</li></ul><p><strong>Beladung und DTC</strong></p><ul><li>Symmetrisch ist standardmäßig aus; „Pylon entfernen“ steht oben in der Auswahl</li><li>F-16: Chaff/Flare als 30+120, 60+60 oder 120+30</li><li>Threats: „Von Intel übernehmen“ und Typen aus DCS zur Auswahl</li><li>Route oder Geo-Linie voll: Auswahl auf der Karte schaltet sich ab</li></ul><p><strong>Lineup Card und Ausschnitte</strong></p><ul><li>Reihenfolge der Abschnitte per Ziehen</li><li>Ausschnitte: R1, R2 und R3 einzeln ein- und ausblenden, WPT-Namen zuschalten</li><li>Route und Funk kommen immer automatisch aus dem Flight</li></ul><p><strong>Oberfläche</strong></p><ul><li>Top-Bar aufgeräumt: Export und Öffnen im Menü, IADS abgesetzt (durchgehend mit grünem Punkt, wenn das Script in der Mission ist)</li><li>Server-Missionen zeigen keinen gelben Ungespeichert-Punkt mehr neben „Gespeichert“</li><li>Flights löschen; KI-Flights bekommen ein DCS-Callsign</li></ul><h2 id="_0-5-10-·-05-11-2026" tabindex="-1">0.5.10 · 05.11.2026 <a class="header-anchor" href="#_0-5-10-·-05-11-2026" aria-label="Permalink to &quot;0.5.10 · 05.11.2026&quot;">​</a></h2><p><strong>Zusammen mit dem Mission Editor</strong></p><ul><li>Die Desktop-App lädt die offene Mission von selbst neu, sobald du sie im DCS Mission Editor speicherst. Deine ungespeicherten Änderungen bleiben erhalten, bei gleichen Stellen gilt der ME (<a href="/dcs/speichern#zusammen-mit-dem-mission-editor">mehr</a>)</li><li>Verwirft der ME die Shardwing-Planungsdaten, schreibt Shardwing sie beim nächsten Speichern wieder hinein</li></ul><p><strong>Flights anlegen</strong></p><ul><li>Auch auf einer Seite ohne Einheiten: Shardwing bietet CJTF Blue/USA bzw. CJTF Red/Russia an und legt das Land beim Speichern mit an</li></ul><h2 id="_0-5-9-·-05-11-2026" tabindex="-1">0.5.9 · 05.11.2026 <a class="header-anchor" href="#_0-5-9-·-05-11-2026" aria-label="Permalink to &quot;0.5.9 · 05.11.2026&quot;">​</a></h2><p><strong>Flights anlegen</strong></p><ul><li>Neue F-16C- und F/A-18C-Flights direkt in Shardwing: Anzahl, Spieler oder KI, Aufgabe, Callsign und Start</li><li>Tanker und AWACS anlegen: Typ, Seite, Start in der Luft, von der Startbahn oder kalt bzw. heiß vom Parkplatz, mit Callsign, Frequenz und TACAN; danach gleich den Track zeichnen</li><li>Flights duplizieren und entfernen (Flight-Kopf)</li><li>Startart und Parkplatz pro Maschine über der Route, automatisch nebeneinander oder per Klick</li><li>Parkplätze farbig auf der Karte, mit Popup zu Größe und Belegung</li></ul><p><strong>Timing</strong></p><ul><li>Fenster in Minuten statt Sekunden, auch auf den Kneeboards</li><li>Bei „+ Sollzeit“ direkt einen Planungspunkt wählen; ohne Punkt bleibt es eine normale Sollzeit</li></ul><p><strong>Karte</strong></p><ul><li><kbd>Esc</kbd> schließt Popups und lässt die Auswahl los; auf der Flight-Seite bleibt der Flight gewählt</li></ul><h2 id="_0-5-8-·-03-11-2026" tabindex="-1">0.5.8 · 03.11.2026 <a class="header-anchor" href="#_0-5-8-·-03-11-2026" aria-label="Permalink to &quot;0.5.8 · 03.11.2026&quot;">​</a></h2><p><strong>Funk</strong></p><ul><li>Gruppenfrequenz jedes Flights unter Units &amp; Funk einstellen (nur Designer), wird beim Speichern in die Mission geschrieben</li><li>Hinweis bei doppelter Frequenz, Frequenz außerhalb des Rasters oder auf einem Netz des Comm Plans</li><li>Frequenzen verteilen: jeder Spieler-Flight bekommt eine eigene freie Frequenz</li></ul><p><strong>Tanker und AWACS</strong></p><ul><li>KI-Skript zum Einschalten: bei Bingo über die Exit-Route heim statt quer durchs Gebiet</li><li>Ablösung durch eine zweite Gruppe mit Late Activation, Startzeit wird ausgerechnet</li></ul><h2 id="_0-5-7-·-03-11-2026" tabindex="-1">0.5.7 · 03.11.2026 <a class="header-anchor" href="#_0-5-7-·-03-11-2026" aria-label="Permalink to &quot;0.5.7 · 03.11.2026&quot;">​</a></h2><p><strong>Tanker</strong></p><ul><li>Track mit Inbound-Kurs und Leg-Länge einstellen, der Anfang des Tracks bleibt liegen</li><li>ARIP-Linie entfällt in allen Tanker-Tracks</li></ul><p><strong>Planungspunkte</strong></p><ul><li>Punkt sitzt genau auf der Koordinate und bleibt beim Zoomen dort</li><li>AR-Punkt lässt sich mit dem Track eines Tankers verbinden und wandert mit</li><li>Orte ohne Zeit: erscheinen nur in der DTC, nicht in Sollzeiten und Prüfungen</li><li>Timing-Gantt zeigt Sollzeiten und Planungspunkte als Rauten</li></ul><h2 id="_0-5-6-·-02-11-2026" tabindex="-1">0.5.6 · 02.11.2026 <a class="header-anchor" href="#_0-5-6-·-02-11-2026" aria-label="Permalink to &quot;0.5.6 · 02.11.2026&quot;">​</a></h2><p><strong>Treffpunkte</strong></p><ul><li>Planungspunkte (RV, Marshal, Holding, CP, IP, Push, Fence, AR) in den Zeichnungen setzen; ein Flight sieht nur die Punkte, an denen er eingetragen ist</li><li>Mehrere Flights an einem Punkt mit eigener Zeit und eigenem Höhenband; Zeiten staffeln, Bänder stapeln, Warnung bei Überlappung</li><li>Holding-Punkte zeichnen ein HOLD-Muster für alle Flights, auf der Karte und im F10</li><li>„Übertragen auf …“: Auftrag, Push, Sollzeiten, Höhenblock, AAR und Notiz auf andere Flights kopieren, mit Zeit- und Höhenschritt</li><li>TOS-Rechner zeigt das Höhenband und setzt die Routenhöhe des Steerpoints auf die Unterkante</li><li>Sollzeiten im Timing übersichtlicher, jede als eigene Karte</li></ul><p><strong>Tanker und AWACS</strong></p><ul><li>Auftrag für KI-Tanker und -AWACS: Callsign, Funk und TACAN, Vorschlag für den Comm Plan</li><li>Track zeichnen (Race-Track oder Kreis, Seite tauschen), wird als Orbit in die Route geschrieben</li><li>Entry- und Exit-Route um den Track, Landeplatz wählbar, Hinweis bei SAM-Ringen</li><li>Zeitplan mit On und Off Track; Shardwing rechnet die nötige Startzeit vor</li><li>Tanker-Track als Treffpunkt im TOS-Rechner</li><li>KI-Flights zeigen DTC, Angriff und Lineup Card nur noch, wo es Sinn ergibt</li></ul><p><strong>Sonst</strong></p><ul><li>Karte mit W, A, S, D verschieben, mit Shift schneller</li><li>Lineup Card: leere 9-Line-Seite (CAS Brief)</li><li>Beladung: CBU-103 und CBU-105 mit Canister-Symbol</li></ul><h2 id="_0-5-5-·-02-11-2026" tabindex="-1">0.5.5 · 02.11.2026 <a class="header-anchor" href="#_0-5-5-·-02-11-2026" aria-label="Permalink to &quot;0.5.5 · 02.11.2026&quot;">​</a></h2><ul><li>Neuer Startbildschirm mit „Beispiel ansehen“: öffnet die Demo-Mission „Operation Desert Veil“</li><li>Startbildschirm zeigt zuletzt geöffnete Missionen und was neu ist</li><li>Handbuch jetzt unter handbuch.shardwing.de</li></ul><h2 id="_0-5-4-·-02-11-2026" tabindex="-1">0.5.4 · 02.11.2026 <a class="header-anchor" href="#_0-5-4-·-02-11-2026" aria-label="Permalink to &quot;0.5.4 · 02.11.2026&quot;">​</a></h2><ul><li>Übersicht: Halten am Push-Punkt zählt mit, keine falsche Meldung „Push laut Route“ mehr</li><li>Handbuch: neue Bilder mit der Demo-Mission „Operation Desert Veil“, Checklisten für Designer, Flight Lead und Wingman</li></ul><h2 id="_0-5-3-·-02-11-2026" tabindex="-1">0.5.3 · 02.11.2026 <a class="header-anchor" href="#_0-5-3-·-02-11-2026" aria-label="Permalink to &quot;0.5.3 · 02.11.2026&quot;">​</a></h2><p><strong>Timing</strong></p><ul><li>Startzeit der Mission änderbar (Designer), wird in die .miz geschrieben</li><li>Gantt: gezogene Kanten haften dezent an Wegpunkten, H und anderen Fenstern (Alt schaltet ab)</li><li>Sollzeiten mit optionalem Ort: der Flight setzt seinen Steerpoint beim Zuordnen dorthin</li><li>AAR-Slots im TOS-Rechner als Info, zählen nur mit Zuordnung</li><li>DEAD auch als TOT statt Fenster</li><li>TOS-Rechner: GS-Spalte richtig ausgerichtet</li></ul><h2 id="_0-5-2-·-02-11-2026" tabindex="-1">0.5.2 · 02.11.2026 <a class="header-anchor" href="#_0-5-2-·-02-11-2026" aria-label="Permalink to &quot;0.5.2 · 02.11.2026&quot;">​</a></h2><p><strong>Timing</strong></p><ul><li>Weitere Sollzeiten pro Flight (z. B. RV, IP) ohne festen Wegpunkt; Zeiten auch als Uhrzeit eingeben</li><li>TOS-Rechner in der DTC (NAV): Sollzeiten Steerpoints zuordnen, eigene Zeiten und Halten, TOS auf Knopfdruck übernehmen</li><li>TOS aus der Cartridge bleiben bei Client-Slots stehen (Wegpunkt-Tabelle im Timing zeigt sie jetzt)</li></ul><p><strong>IADS und Server</strong></p><ul><li>Netz-Ansicht ordnet die Symbole wie auf der Karte, verrutscht beim Verbinden nicht mehr; „Nach Ebenen“ als Alternative</li><li>Warnung „Nicht gespeichert: Das IADS hat … Fehler“ verschwindet nach 20 s</li><li>Server-Verwaltung unter <code>#/admin</code>, Missionen löschen und automatischer Ablauf</li></ul><h2 id="_0-5-1-·-01-11-2026" tabindex="-1">0.5.1 · 01.11.2026 <a class="header-anchor" href="#_0-5-1-·-01-11-2026" aria-label="Permalink to &quot;0.5.1 · 01.11.2026&quot;">​</a></h2><p><strong>Rechtliches</strong></p><ul><li>Impressum, Datenschutz und Lizenzen in der App (Menü, Startseite, Anmeldeseite)</li><li>Kneeboard-Karten auf OpenStreetMap-Grundkarte, Satellitenkarte entfernt</li><li>MOOSE-Lizenz liegt mit dem IADS in der Mission</li><li>Hinweis beim Teilen: nur hochladen, was du teilen darfst</li></ul><h2 id="_0-5-0-·-01-11-2026" tabindex="-1">0.5.0 · 01.11.2026 <a class="header-anchor" href="#_0-5-0-·-01-11-2026" aria-label="Permalink to &quot;0.5.0 · 01.11.2026&quot;">​</a></h2><p><strong>IADS-Werkzeug</strong></p><ul><li>SAM-Übersicht: alle Luftabwehr-Gruppen mit Filtern und Hinweisen, Benennen nach Konvention in einem Rutsch</li><li>Netz-Editor mit Daten-, Strom- und Schutz-Verbindungen, Was-wäre-wenn</li><li>Export ins Mission Script: MOOSE, EMCON, IADS und Netz-Datei per MISSION-START-Trigger</li><li>Warnung bei fremden IADS-Skripten</li></ul><h2 id="_0-4-0-·-31-10-2026" tabindex="-1">0.4.0 · 31.10.2026 <a class="header-anchor" href="#_0-4-0-·-31-10-2026" aria-label="Permalink to &quot;0.4.0 · 31.10.2026&quot;">​</a></h2><p><strong>Attack Planner</strong></p><ul><li>Direct, Indirect, Wheel, Toss, Standoff und Standoff mit Pull-up</li><li>Profil und Draufsicht, Attack Card fürs Kneeboard</li></ul><h2 id="_0-3-0-·-31-10-2026" tabindex="-1">0.3.0 · 31.10.2026 <a class="header-anchor" href="#_0-3-0-·-31-10-2026" aria-label="Permalink to &quot;0.3.0 · 31.10.2026&quot;">​</a></h2><p><strong>Kneeboards aufgeräumt</strong></p><ul><li>Cockpit-Satz aus Lineup Card, Comm Card und Route</li><li>Comm Card mit Netz-Farben, Diverts, Index mit Seitenzahlen, Nachtmodus, vorbelegte Vorlagen</li><li>Kneeboards und Paketinfos ohne KI-Flights</li></ul><h2 id="_0-2-1-·-31-10-2026" tabindex="-1">0.2.1 · 31.10.2026 <a class="header-anchor" href="#_0-2-1-·-31-10-2026" aria-label="Permalink to &quot;0.2.1 · 31.10.2026&quot;">​</a></h2><ul><li>Timing: Client-Slots starten zum nötigen Zeitpunkt, Hinweis bei Vul deutlich zu früh</li></ul><h2 id="_0-2-0-·-31-10-2026" tabindex="-1">0.2.0 · 31.10.2026 <a class="header-anchor" href="#_0-2-0-·-31-10-2026" aria-label="Permalink to &quot;0.2.0 · 31.10.2026&quot;">​</a></h2><ul><li>Timing als Gantt mit Rollen-Gruppen, Rückwärtsplanung bis zum Anlassen, Sonnenzeiten, Zoom</li><li>Tanker-Slots (AAR) und entschärfte Deconfliction</li><li>Wegpunkt-Tabelle mit TOS, Wegpunkte in Tabellen bearbeiten</li><li>Rückgängig/Wiederherstellen für jede Änderung</li><li>Callsign-Vorschläge nach Rolle</li><li>Panel auf ganze Höhe (<kbd>⌘⇧↵</kbd>)</li></ul><h2 id="_0-1-6-–-0-1-7-·-29-10-2026" tabindex="-1">0.1.6 – 0.1.7 · 29.10.2026 <a class="header-anchor" href="#_0-1-6-–-0-1-7-·-29-10-2026" aria-label="Permalink to &quot;0.1.6 – 0.1.7 · 29.10.2026&quot;">​</a></h2><ul><li>Beladung: Stationsleiste, Bearbeiten, Freigabe für Piloten</li><li>Eigene Kräfte als NATO-Symbole</li><li>Geteilte Cartridge: ein Flight kann sich eine eigene Kopie anlegen</li></ul><h2 id="_0-1-5-·-29-10-2026" tabindex="-1">0.1.5 · 29.10.2026 <a class="header-anchor" href="#_0-1-5-·-29-10-2026" aria-label="Permalink to &quot;0.1.5 · 29.10.2026&quot;">​</a></h2><ul><li>Zeichnungen: Schalter „Alle Einheiten zeigen“</li><li>Timing: Steerpoints der DTC-Routen 2 und 3 als Push- und Zielpunkt</li><li>Comm Card übernimmt die DTC-Kanäle</li><li>Kartenausschnitt: Vorschau groß, Stellungen pro Ausschnitt ausblendbar</li></ul><h2 id="_0-1-4-·-28-10-2026" tabindex="-1">0.1.4 · 28.10.2026 <a class="header-anchor" href="#_0-1-4-·-28-10-2026" aria-label="Permalink to &quot;0.1.4 · 28.10.2026&quot;">​</a></h2><ul><li>Routen von KI-Flights direkt auf der Karte bearbeiten</li><li>Timing, Deconfliction und Lagekarte nutzen die Route der Cartridge</li><li>Comm Plan: Frequenzen vorschlagen</li><li>Paketübersicht mit Auswahl, Threat-Positionen in jedem Koordinatenformat</li></ul><h2 id="_0-1-2-·-28-10-2026" tabindex="-1">0.1.2 · 28.10.2026 <a class="header-anchor" href="#_0-1-2-·-28-10-2026" aria-label="Permalink to &quot;0.1.2 · 28.10.2026&quot;">​</a></h2><ul><li>Timing mit Sync-Matrix: H-Hour, TOT/Vul/SEAD-Fenster, Push, Deconfliction</li><li>Comm Plan mit Comm Card</li><li>Eigene Callsigns und Aufgaben</li><li>Wetter: METAR je Flugplatz</li><li>Messwerkzeug (Taste M), Zuletzt geöffnet</li></ul><h2 id="_0-1-1-·-28-10-2026" tabindex="-1">0.1.1 · 28.10.2026 <a class="header-anchor" href="#_0-1-1-·-28-10-2026" aria-label="Permalink to &quot;0.1.1 · 28.10.2026&quot;">​</a></h2><ul><li>Kartenausschnitte: eigene Kartenseiten, gedreht, mit Ebenen und Gitter</li><li>Flugplätze und Bodenstationen aller DCS-Karten</li><li>Lagekarte, Bullseye versetzen</li></ul><h2 id="_0-1-0-·-27-10-2026" tabindex="-1">0.1.0 · 27.10.2026 <a class="header-anchor" href="#_0-1-0-·-27-10-2026" aria-label="Permalink to &quot;0.1.0 · 27.10.2026&quot;">​</a></h2><p>Erste Version mit automatischen Updates: Missionen und Cartridges öffnen, bearbeiten und am Ort speichern; gemeinsam planen über den Shardwing-Server.</p>',155)])])}const c=n(r,[["render",a]]);export{m as __pageData,c as default};
